<script setup>
import { ref, onMounted, computed, watch } from 'vue'
import { db, DEFAULT_TEMPLATE_ITEMS } from '../db.js'

const selectedPositionId = ref(null)
const newPositionName = ref('')
const editingPositionId = ref(null)
const editedPositionName = ref('')

const editingItemId = ref(null)
const editedItemName = ref('')
const editedItemCategory = ref('Живлення')
const editedItemStatus = ref('На позиції')

const category = ref('Живлення')
const itemName = ref('')
const status = ref('На позиції')
const quantity = ref(0)
const notes = ref('')

const positions = ref([])
const items = ref([])

const loadPositions = async () => {
      const posCount = await db.positions.count()
        if (posCount === 0) {
                const initialNames = ['Чіпс', 'Зебра', 'Осло', 'Гарпун']
                    for (const name of initialNames) {
                              const posId = await db.positions.add({ name: `Позиція «${name}»` })
                                    const template = DEFAULT_TEMPLATE_ITEMS.map(i => ({ ...i, positionId: posId }))
                                          await db.items.bulkAdd(template)
                    }
        }
          positions.value = await db.positions.toArray()
            if (positions.value.length > 0 && !selectedPositionId.value) {
                    selectedPositionId.value = positions.value[0].id
            }
}

const loadItems = async () => {
      if (selectedPositionId.value) {
            items.value = await db.items.where('positionId').equals(selectedPositionId.value).toArray()
      } else {
            items.value = []
      }
}

onMounted(async () => {
      await loadPositions()
        await loadItems()
})

watch(selectedPositionId, async () => {
      await loadItems()
})

const addPosition = async () => {
      if (!newPositionName.value.trim()) return
        const posId = await db.positions.add({ name: newPositionName.value.trim() })
          const template = DEFAULT_TEMPLATE_ITEMS.map(i => ({ ...i, positionId: posId }))
            await db.items.bulkAdd(template)
              newPositionName.value = ''
                await loadPositions()
                  selectedPositionId.value = posId
}

const startEditPosition = (pos) => {
      editingPositionId.value = pos.id
        editedPositionName.value = pos.name
}

const saveEditPosition = async (id) => {
      if (!editedPositionName.value.trim()) return
        await db.positions.update(id, { name: editedPositionName.value.trim() })
          editingPositionId.value = null
            await loadPositions()
}

const deletePosition = async (id) => {
      if (confirm('Видалити позицію та все майно на ній?')) {
            await db.items.where('positionId').equals(id).delete()
                await db.positions.delete(id)
                    await loadPositions()
                        if (positions.value.length > 0) {
                                  selectedPositionId.value = positions.value[0].id
                        } else {
                                  selectedPositionId.value = null
                        }
      }
}

const addItem = async () => {
      if (!itemName.value.trim() || !selectedPositionId.value) return
        await db.items.add({
                positionId: selectedPositionId.value,
                    category: category.value,
                        itemName: itemName.value.trim(),
                            status: status.value,
                                quantity: Number(quantity.value),
                                    notes: notes.value
        })
          itemName.value = ''
            notes.value = ''
              quantity.value = 0
                await loadItems()
}

const updateItemQty = async (id, newQty) => {
      await db.items.update(id, { quantity: Number(newQty) })
        await loadItems()
}

const startEditItem = (item) => {
      editingItemId.value = item.id
        editedItemName.value = item.itemName
          editedItemCategory.value = item.category
            editedItemStatus.value = item.status
}

const saveEditItem = async (id) => {
      if (!editedItemName.value.trim()) return
        await db.items.update(id, {
                itemName: editedItemName.value.trim(),
                    category: editedItemCategory.value,
                        status: editedItemStatus.value
        })
          editingItemId.value = null
            await loadItems()
}

const deleteItem = async (id) => {
      await db.items.delete(id)
        await loadItems()
}

const activeItems = computed(() => items.value?.filter(i => i.status === 'На позиції') || [])
const neededItems = computed(() => items.value?.filter(i => i.status === 'Потреба') || [])
const brokenItems = computed(() => items.value?.filter(i => i.status === 'Неробочий стан') || [])
</script>

<template>
  <div class="sklad-container">
      <h2>Облік майна та позицій</h2>

          <!-- Блок керування позиціями -->
              <div class="pos-management">
                    <div class="pos-select-group">
                            <label><b>Позиція:</b></label>
                                    <select v-model="selectedPositionId" class="styled-select">
                                              <option v-for="pos in positions" :key="pos.id" :value="pos.id">{{ pos.name }}</option>
                                                      </select>

                                                              <template v-for="pos in positions" :key="'edit-'+pos.id">
                                                                        <div v-if="pos.id === selectedPositionId" class="pos-actions">
                                                                                    <template v-if="editingPositionId === pos.id">
                                                                                                  <input v-model="editedPositionName" class="styled-input" />
                                                                                                                <button @click="saveEditPosition(pos.id)" class="btn btn-save">Зберегти</button>
                                                                                                                            </template>
                                                                                                                                        <template v-else>
                                                                                                                                                      <button @click="startEditPosition(pos)" class="btn btn-edit">Редагувати</button>
                                                                                                                                                                    <button @click="deletePosition(pos.id)" class="btn btn-del">Видалити</button>
                                                                                                                                                                                </template>
                                                                                                                                                                                          </div>
                                                                                                                                                                                                  </template>
                                                                                                                                                                                                        </div>

                                                                                                                                                                                                              <form @submit.prevent="addPosition" class="inline-form">
                                                                                                                                                                                                                      <input v-model="newPositionName" placeholder="Нова позиція..." class="styled-input" />
                                                                                                                                                                                                                              <button type="submit" class="btn btn-add">Додати позицію</button>
                                                                                                                                                                                                                                    </form>
                                                                                                                                                                                                                                        </div>

                                                                                                                                                                                                                                            <!-- Основний контент для обраної позиції -->
                                                                                                                                                                                                                                                <div v-if="selectedPositionId" class="content-box">
                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                            <!-- Форма додавання майна -->
                                                                                                                                                                                                                                                                  <form @submit.prevent="addItem" class="add-form">
                                                                                                                                                                                                                                                                          <h4>Додати новий елемент або дрон</h4>
                                                                                                                                                                                                                                                                                  <div class="grid-form">
                                                                                                                                                                                                                                                                                            <select v-model="category" class="styled-select">
                                                                                                                                                                                                                                                                                                        <option value="Живлення">Живлення</option>
                                                                                                                                                                                                                                                                                                                    <option value="Зв'язок">Зв'язок</option>
                                                                                                                                                                                                                                                                                                                                <option value="БПЛА">БПЛА</option>
                                                                                                                                                                                                                                                                                                                                            <option value="Інше">Інше</option>
                                                                                                                                                                                                                                                                                                                                                      </select>

                                                                                                                                                                                                                                                                                                                                                                <input v-model="itemName" placeholder="Назва (напр. Мавік 3)..." class="styled-input" required />

                                                                                                                                                                                                                                                                                                                                                                          <select v-model="status" class="styled-select">
                                                                                                                                                                                                                                                                                                                                                                                      <option value="На позиції">На позиції</option>
                                                                                                                                                                                                                                                                                                                                                                                                  <option value="Потреба">Потреба</option>
                                                                                                                                                                                                                                                                                                                                                                                                              <option value="Неробочий стан">Неробочий стан</option>
                                                                                                                                                                                                                                                                                                                                                                                                                        </select>

                                                                                                                                                                                                                                                                                                                                                                                                                                  <div class="qty-notes-row">
                                                                                                                                                                                                                                                                                                                                                                                                                                              <input type="number" v-model="quantity" min="0" placeholder="К-ть" class="styled-input qty-input" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                          <input v-model="notes" placeholder="Примітки / номер" class="styled-input notes-input" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <button type="submit" class="btn btn-success">Додати елемент</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </form>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <!-- 3 таблиці у горизонтальному контейнері зі скролом -->
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div class="tables-scroll-container">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div class="tables-grid">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <!-- На позиції -->
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div class="col green">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <h3>🟢 Що є на позиції</h3>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div class="table-wrap">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <table class="styled-table">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <thead>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <tr>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <th class="th-name">Назва / Дрон</th>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <th class="th-qty">К-ть</th>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <th class="th-action">Дії</th>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </tr>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </thead>
